SELECT singer.Name, singer.Age AS youngest_singer FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID WHERE singer.Age = (SELECT MIN(Age) FROM singer);
