SELECT DISTINCT Country, COUNT(*) AS Total_Singers FROM singer GROUP BY Country;
SELECT singer.Name AS Song_Name, singer.Age AS Age FROM singer INNER JOIN concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN stadium ON singer_in_concert.Stadium_ID = stadium.Stadium_ID WHERE singer.Age > (SELECT AVG(Age) FROM singer)
SELECT singer.Name, singer.Age FROM singer INNER JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID INNER JOIN stadium ON singer_in_concert.Stadium_ID = stadium.Stadium_ID WHERE singer.Age > (SELECT AVG(Age) FROM singer)
SELECT stadium.Location, stadium.Name, concert.Year FROM concert JOIN singer_in_concert ON concert.concert_ID = singer_in_concert.concert_ID JOIN stadium ON singer_in_concert.Stadium_ID = stadium.Stadium_ID WHERE concert.Year BETWEEN 5000 AND 10000;
