SELECT Professionals.professional_id, Professionals.last_name, Professionals.cell_number FROM Professionals JOIN Owners ON Professionals.owner_id = Owners.owner_id WHERE Owners.state = 'Indiana' OR Professionals.cell_number IS NOT NULL GROUP BY Professionals.professional_id, Professionals.last_name, Professionals.cell_number
SELECT p.professional_id, p.last_name, p.cell_number FROM Professionals p JOIN Treatments t ON p.professional_id = t.professional_id JOIN Dogs d ON t.dog_id = d.dog_id JOIN Owners o ON d.owner_id = o.owner_id WHERE p.state = 'Indiana' OR t.treatment_type_code = (SELECT treatment_type_code FROM Treatment_Types WHERE treatment_type_description = 'More than two treatments')
SELECT Dogs.name, Owners.first_name, Owners.last_name, Owners.street, Owners.city, Owners.state, Owners.zip_code, Owners.email_address, Owners.home_phone, Owners.cell_number FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Dogs.date_of_birth IS NULL OR Dogs.date_of_birth >= DATE_SUB(CURDATE(), INTERVAL 10 DAY) AND Dogs.owner_id IN (SELECT Owners.owner_id FROM Owners) AND Dogs.owner_id IN (SELECT Professionals.professional_id FROM Professionals) AND Dogs.breed_code = (SELECT Breeds.breed_code FROM Breeds) AND Dogs.size_code = (SELECT Sizes.size_code FROM Sizes) AND Dogs.name IS NOT NULL;
SELECT o.owner_id, o.first_name, o.last_name, o.street, o.city, o.state, o.zip_code, o.email_address, o.home_phone, o.cell_number, d.name, d.age, d.date_of_birth, d.gender, d.date_arrived, d.date_departed, d.date_adopted, d.date_departed FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id;
SELECT Dogs.id, Dogs.first_name, Dogs.last_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id ORDER BY Dogs.age DESC LIMIT 1;
SELECT Dogs.id, Dogs.role, Dogs.first_name FROM Dogs INNER JOIN Professionals ON Dogs.owner_id = Professionals.owner_id WHERE Dogs.abandoned_yn = 'N' AND Dogs.date_of_birth IS NOT NULL;
SELECT Dogs.id, Dogs.role, Dogs.first_name, Professionals.professional_id, Professionals.first_name FROM Dogs INNER JOIN Professionals ON Dogs.owner_id = Professionals.owner_id WHERE Dogs.treatment_id IS NOT NULL OR Professionals.treatment_type_code IN ('2', '3')
SELECT treatment_type_description FROM Treatment_Types WHERE cost_of_treatment < (SELECT MIN(cost_of_treatment) FROM Charges)
SELECT treatment_type_description FROM Treatment_Types ORDER BY cost_of_treatment ASC LIMIT 1;
SELECT o.owner_id, o.zip_code, d.dog_id, d.date_arrived, d.date_departed FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id GROUP BY o.owner_id, o.zip_code ORDER BY d.date_departed DESC LIMIT 1;
SELECT Dogs.owner_id, Dogs.zip_code FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id INNER JOIN Professionals ON Treatments.professional_id = Professionals.professional_id INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code WHERE Treatments.cost_of_treatment IS MAX(Cost_of_treatment) GROUP BY Dogs.owner_id, Dogs.zip_code;
SELECT o.first_name, o.last_name FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Professionals p ON d.owner_id = p.professional_id WHERE d.date_of_treatment < (SELECT date_of_treatment FROM Charges WHERE charge_type = 'cheaper' AND charge_amount < (SELECT AVG(charge_amount) FROM Charges))
