SELECT o.first_name, d.name FROM Owners o INNER JOIN Dogs d ON o.owner_id = d.owner_id WHERE o.state = 'Virginia' AND d.state = 'Virginia' AND d.abandoned_yn = 'N' AND d.state = 'Virginia';
SELECT Dogs.name, Owners.first_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Owners.state = 'Virginia' AND Owners.state = 'VA'
SELECT Dogs.owner_id, Owners.last_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Dogs.age = (SELECT MIN(age) FROM Dogs)
SELECT o.last_name, d.age FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id WHERE d.age = (SELECT MIN(age) FROM Dogs)
SELECT o.email_address FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Professionals p ON d.professional_id = p.professional_id WHERE o.state = 'Hawaii' OR o.state = 'Wisconsin' AND p.email_address IS NOT NULL;
SELECT email_address FROM Owners INNER JOIN Dogs ON Owners.owner_id = Dogs.owner_id INNER JOIN Professionals ON Dogs.dog_id = Professionals.professional_id WHERE state = 'Hawaii' OR state = 'Wisconsin'
SELECT COUNT(DISTINCT Dogs.age) FROM Dogs;
SELECT COUNT(DISTINCT Dogs.age) FROM Dogs;
SELECT MAX(cost_of_treatment) FROM Treatments;
SELECT cost_of_treatment FROM Treatments WHERE date_of_treatment = (SELECT MAX(date_of_treatment) FROM Treatments)
SELECT Dogs.name, Dogs.age, Dogs.weight FROM Dogs INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id;
SELECT Dogs.name, Dogs.age, Dogs.weight FROM Dogs INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id;
SELECT Name FROM singer ORDER BY Net_Worth_Millions ASC
SELECT Name FROM singer ORDER BY Net_Worth_Millions ASC
SELECT Name FROM singer WHERE Citizenship != 'French'
SELECT Name FROM singer WHERE Citizenship != 'French' AND Name IS NOT NULL
SELECT Name FROM singer WHERE Birth_Year IN (1948, 1949)
SELECT Name FROM singer WHERE Birth_Year IN (1948, 1949) GROUP BY Name
SELECT Name FROM singer ORDER BY Net_Worth_Millions DESC LIMIT 1
SELECT DISTINCT Citizenship, COUNT(*) AS Number_of_Singers_per_Citizenship FROM singer GROUP BY Citizenship;
SELECT DISTINCT singer.Citizenship, COUNT(singer.Singer_ID) AS total_singers FROM singer JOIN song ON singer.Singer_ID = song.Singer_ID GROUP BY singer.Citizenship
SELECT DISTINCT Citizenship FROM singer ORDER BY Citizenship ASC LIMIT 1
SELECT DISTINCT singer.Citizenship, singer.Name, singer.Sales, singer.Net_Worth_Millions FROM singer JOIN song ON singer.Singer_ID = song.Singer_ID WHERE song.Sales IS NOT NULL;
SELECT DISTINCT Citizenship, MAX(Song_Highest_Position) AS Max_Net_Worth FROM singer JOIN song ON song.Singer_ID = singer.Singer_ID GROUP BY Citizenship;
SELECT MAX(Singer.Net_Worth_Millions) AS Max_Net_Worth FROM singer;
SELECT DISTINCT singer.Name FROM singer JOIN song ON song.Singer_ID = singer.Singer_ID WHERE song.Sales > 300000;
SELECT DISTINCT s.Name FROM singer s JOIN song s2 ON s.Singer_ID = s2.Singer_ID WHERE s2.Sales > 300000;
SELECT DISTINCT Citizenship FROM singer WHERE Birth_Year < 1945 AND Birth_Year > 1955;
SELECT Citizenship FROM singer WHERE Birth_Year < 1945 AND Citizenship = (SELECT Citizenship FROM singer WHERE Birth_Year > 1955)
SELECT property_name, property_address FROM Properties WHERE property_type_code = 'apartment' AND property_type_code = 'house' AND room_count > 1;
